from lib import *
S = SS('v59')
steps = [
    step("优先级与 overprovisioning factor。dc1(优先级 0)四个后端、dc2(优先级 1)四个后端,Envoy 做主动健康检查(0.5 s 一次,连续 2 次失败算不健康),依次停掉 dc1 的后端。默认的 factor 140:停 1 个(健康 75%)时 100.0% 的请求仍落在 dc1;停 2 个(50%)时 69.8% 在 dc1、30.2% 溢出到 dc2;停 3 个(25%)时 33.6% / 66.4%;全停时 100.0% 在 dc2。factor 100:停 1 个就是 74.6% / 25.4%,停 2 个 50.9% / 49.1%,停 3 个 24.1% / 75.9%。所有情形下错误数都是 0。留在 dc1 的比例大约是健康比例乘以 factor/100(封顶 100%)。", t=tl(S(1)), mark=lidx(S(1), '69.8%', '33.6%', '74.6%'), done=lidx(S(1), '50.9%', '24.1%'), b=bars([['factor 140、停 1 个:dc2 占比', 0, '0.0%'], ['factor 140、停 2 个:dc2 占比', 30.2, '30.2%'], ['factor 100、停 1 个:dc2 占比', 25.4, '25.4%'], ['factor 100、停 2 个:dc2 占比', 49.1, '49.1%']], 50, done=[0], mark=[1, 2, 3]), kv=KV([['factor 140,dc1 剩 75%', '全部留在 dc1(0.0% 溢出)'], ['factor 140,dc1 剩 50%', '69.8% / 30.2%'], ['factor 100,dc1 剩 75%', '74.6% / 25.4%'], ['dc1 全停', '100.0% 到 dc2,错误 0']], ['factor 140,dc1 剩 50%'])),
    step("dc1 整体挂掉的切换。以 100 个/秒的开环负载跑 8 s,在第 2.5 s 同时停掉 dc1 的四个后端(共 800 个请求)。(a)主动健康检查(0.5 s,2 次失败):失败 172 个,失败的请求在停机后 0.02 到 1.85 s 之间,1.86 s 起由 dc2 成功响应。(b)只有被动异常点检测(连续 3 次本地来源失败摘除,检测间隔 0.5 s):失败 95 个,0.02 到 1.11 s,1.12 s 起切到 dc2。(c)两者都没有:失败 535 个,一直到结束都没有切过去。另一个观察:健康检查 interval 设 0.5 s、no_traffic_interval 保持默认值时,先发了 20 个请求再停掉一个 dc1 后端,Envoy 过了 59.0 s 才把它标成不健康;写上 no_traffic_interval: 0.5s 之后前面的实验里是 1 s 左右。", t=tl(S(2)), mark=lidx(S(2), '(c)两者都没有', '另一个观察'), done=lidx(S(2), '(a)主动', '(b)只有'), b=bars([['(a)主动检查:失败的请求', 172, '172'], ['(b)被动检测:失败的请求', 95, '95'], ['(c)两者都没有:失败的请求', 535, '535(没切过去)'], ['默认 no_traffic_interval:发现用时 s', 59.0, '59.0']], 535, done=[0, 1], mark=[2, 3]), kv=KV([['主动健康检查', '失败 172 个,1.86 s 切过去'], ['被动异常点检测', '失败 95 个,1.12 s 切过去'], ['都没有', '失败 535 个,没切过去'], ['no_traffic_interval 默认', '59.0 s 才发现']], ['no_traffic_interval 默认'])),
    step("就近的好处。dc1 的后端响应延迟 2 ms,dc2 的后端 40 ms(模拟跨机房往返),顺序发 1000 个请求。dc1 优先(优先级 0 / 1):p50 4.0 ms,p99 4.9 ms,100.0% 落在 dc1。不区分机房、八个后端同一优先级轮询:p50 23.4 ms,p99 52.3 ms,50.0% / 50.0% 落在 dc1 / dc2。", t=tl(S(3)), mark=lidx(S(3), '(b)不区分'), done=lidx(S(3), '(a)dc1 优先'), b=bars([['dc1 优先 p50 ms', 4.0, '4.0'], ['dc1 优先 p99 ms', 4.9, '4.9'], ['轮询 p50 ms', 23.4, '23.4'], ['轮询 p99 ms', 52.3, '52.3']], 53, done=[0, 1], mark=[2, 3]), kv=KV([['dc1 优先', 'p50 4.0 ms,p99 4.9 ms'], ['不区分机房', 'p50 23.4 ms,p99 52.3 ms'], ['落点', '50.0% 的请求去了 dc2']], ['不区分机房'])),
    step("nginx 的 backup 与 Envoy 的优先级在部分故障时的区别。nginx 里 dc1 四个后端是普通 server,dc2 四个是 backup。停掉 dc1 的两个后端:100.0% 的请求仍然落在 dc1,剩下的两个后端各承担 750 个(共 1500 个),backup 一个也没有;同样的情形 Envoy(factor 140)是 69.8% 在 dc1、30.2% 溢出到 dc2。再停掉 dc1 剩下的两个:nginx 的请求 100.0% 去了 dc2,四个 backup 各 375 个,错误数都是 0。", t=tl(S(4)), mark=lidx(S(4), 'nginx(a)', 'Envoy(factor 140)'), done=lidx(S(4), 'nginx(b)'), b=bars([['nginx 停 2 个:dc2 占比', 0, '0.0%'], ['Envoy 停 2 个:dc2 占比', 30.2, '30.2%'], ['nginx 全停:dc2 占比', 100, '100.0%']], 100, mark=[0, 1], done=[2]), kv=KV([['nginx backup', '普通 server 全不可用才启用'], ['nginx 停 2 个', '剩下两个各 750 个,backup 为 0'], ['Envoy 优先级', '按健康比例溢出,停 2 个溢出 30.2%']], ['nginx backup'])),
]
A = mkartv('v59', 59, '微服务,多机房,Envoy,优先级,容灾,nginx,真实验证,动画演示',
    '实测多机房路由:Envoy 优先级故障转移在 dc1 剩 75% 健康时仍全部留在 dc1(factor 140),剩 50% 时 30.2% 溢出到 dc2;dc1 全挂后主动检查约 1.86 s 切走、失败 172 个,什么检查都没配则一直不切(失败 535 个);就近让 p50 从 23.4 ms 降到 4.0 ms;nginx 的 backup 在 dc1 剩一半时一个都不接。',
    '多机房部署时怎么就近调用、又在机房出问题时跨机房容灾?Envoy 的优先级和 overprovisioning factor 什么时候开始溢出?主动检查和被动检测切换要多久?nginx 的 backup 有什么不同?这篇用 Envoy 1.39.3 和 nginx 1.31.6 逐项量出来。',
    [('100.0% → 69.8%', 'factor 140 时,dc1 剩 75% 与剩 50% 健康时留在 dc1 的请求比例(剩 50% 时 30.2% 溢出到 dc2)'), ('59.0 s', '主动检查 interval 0.5 s 但 no_traffic_interval 保持默认时,Envoy 发现一个停掉的后端的用时'), ('23.4 ms → 4.0 ms', '跨机房轮询与就近(dc1 优先)的 p50 延迟(dc2 后端模拟 40 ms)')],
    [('优先级与 factor', '<p>留在优先机房的比例约为健康比例乘以 factor/100,封顶 100%,其余溢出到下一优先级。</p>'),
     ('整体切换', '<p>主动检查要连续失败几次才摘除,被动检测靠真实失败;什么都不配则不会切换;no_traffic_interval 默认值会让检查非常慢。</p>'),
     ('就近的收益', '<p>优先级 0 的机房健康时,所有请求都留在本机房,延迟明显更低。</p>'),
     ('nginx backup 与 Envoy', '<p>nginx 的 backup 只在普通 server 全不可用时才接流量,Envoy 按健康比例逐步溢出。</p>')],
    steps,
    [ENV_V + '。Envoy 是 1.39.3,nginx 是 1.31.6,八个后端是本进程里的 Python 服务;“机房”只是后端分成两组,跨机房的代价用 dc2 后端额外的响应延迟模拟,不是真实的网络或距离;第二节每种配置只测了 1 次开环负载(100 个/秒,8 s);第一节每一格 1500 个顺序请求,比例有几个百分点的随机波动',
     '没有验证:真实的跨机房网络(带宽、丢包、费用);容量问题:溢出的流量超过 dc2 的容量会不会把 dc2 也压垮;Envoy 的 locality 加权负载均衡(locality_weighted_lb_config)与 zone 感知路由;注册中心层面的多数据中心(Consul WAN、Nacos 多集群同步);跨机房的数据一致性与读写路由;DNS 层面的 GSLB'],
    '多机房就近路由与容灾')
